        this.rom = jt.ROM.loadState(state.r);
        bytes = jt.Util.uncompressStringBase64ToInt8BitArray(state.b, bytes);
        slice0AddressOffset = state.s0;
        slice1AddressOffset = state.s1;
        slice2AddressOffset = state.s2;
